// d-Billing.java - JVM reference of billing algorithm A (single-file source). Run: java d-Billing.java <vectors.json>
// Minimal JSON reading by regex because the vectors file is machine-generated by d-billing-gen.py (no library, no network).
import java.nio.file.*; import java.util.*; import java.util.regex.*;
public class Billing {
  public static void main(String[] a) throws Exception {
    String s = Files.readString(Path.of(a[0]));
    Matcher m = Pattern.compile("\\{\"id\": (\\d+), \"segments\": \\[(.*?)\\], \"min_billable_minutes\": (\\d+), \"increment_minutes\": (\\d+), \"mode\": \"(\\w+)\"\\}").matcher(s);
    Pattern sp = Pattern.compile("\"elapsed_ms\": (\\d+), \"rate_pph\": (\\d+)");
    StringBuilder out = new StringBuilder();
    while (m.find()) {
      long total = 0, num = 0, lastRate = 0; Matcher x = sp.matcher(m.group(2));
      while (x.find()) { long e = Long.parseLong(x.group(1)), r = Long.parseLong(x.group(2)); total += e; num += e * r; lastRate = r; }
      long min = Long.parseLong(m.group(3)) * 60000, unit = Long.parseLong(m.group(4)) * 60000; String mode = m.group(5);
      long f = Math.max(total, min), r;
      if (mode.equals("up")) r = (f + unit - 1) / unit * unit; else if (mode.equals("down")) r = f / unit * unit; else r = (2 * f + unit) / (2 * unit) * unit;
      r = Math.max(r, min); num += (r - total) * lastRate;
      out.append(m.group(1)).append(',').append(Math.floorDiv(2 * num + 3600000L, 2 * 3600000L)).append('\n');
    }
    System.out.print(out);
  }
}
